1	/**
2	 * Builds an inline script tag that reads `data-src` from the first iframe
3	 * in the script's parent element, detects the nearest non-transparent ancestor
4	 * background color, appends it as a `background` query param, and sets `src`
5	 * to trigger a single load with the correct background.
6	 *
7	 * Uses `document.currentScript` to scope to the containing card, so multiple
8	 * instances on the same page each target their own iframe.
9	 *
10	 * @param {Document} document
11	 * @returns {HTMLScriptElement} A script element
12	 */
13	export function buildSrcBackgroundScript(document) {
14	    function setSrcBackgroundFromParent() {
15	        const script = document.currentScript;
16	        if (!script) {
17	            return;
18	        }
19	
20	        const el = script.parentElement.querySelector('iframe[data-src]');
21	        if (!el) {
22	            return;
23	        }
24	
25	        const baseSrc = el.getAttribute('data-src');
26	
27	        function colorToRgb(color) {
28	            const canvas = document.createElement('canvas');
29	            canvas.width = 1;
30	            canvas.height = 1;
31	            const ctx = canvas.getContext('2d');
32	            ctx.fillStyle = color;
33	            ctx.fillRect(0, 0, 1, 1);
34	            const [r, g, b, a] = ctx.getImageData(0, 0, 1, 1).data;
35	            return {r, g, b, a};
36	        }
37	
38	        let node = el.parentElement;
39	        let bg;
40	        while (node) {
41	            bg = window.getComputedStyle(node).backgroundColor;
42	            if (bg && bg !== 'transparent') {
43	                const {a} = colorToRgb(bg);
44	                if (a > 0) {
45	                    break;
46	                }
47	            }
48	            node = node.parentElement;
49	        }
50	
51	        if (!node || !bg || bg === 'transparent') {
52	            el.src = baseSrc;
53	            return;
54	        }
55	
56	        const {r, g, b, a} = colorToRgb(bg);
57	        if (a === 0) {
58	            el.src = baseSrc;
59	            return;
60	        }
61	
62	        const hex = [r, g, b].map(c => c.toString(16).padStart(2, '0')).join('');
63	        const u = new URL(baseSrc);
64	        u.searchParams.set('background', hex);
65	        el.src = u.toString();
66	    }
67	
68	    const script = document.createElement('script');
69	    script.innerHTML = `(${setSrcBackgroundFromParent.toString()})()`;
70	    return script;
71	}
